28	const PROCESSING_FEE = 5;
29	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	// Kept as an exact fraction rather than `amount * 0.1`, which drifts in
39	// floating point.
40	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
41	  policyBasePremium / 10;
42	
43	const CURSE_SURCHARGE_NUMERATOR = 1;
44	const CURSE_SURCHARGE_DENOMINATOR = 2;
45	
46	// Surcharges attached to a single item are a percentage of that item's own
47	// base premium from the price list (never of the policy base premium).
48	const surchargeForItem = (item: Item): number =>
49	  item.cursed
50	    ? (BASE_PREMIUM_BY_TYPE[item.type] * CURSE_SURCHARGE_NUMERATOR) /
51	      CURSE_SURCHARGE_DENOMINATOR
52	    : 0;
53	
54	const itemSurchargesOf = (items: Item[]): number =>
55	  items.reduce((total, item) => total + surchargeForItem(item), 0);
56	
57	const BLOCK_SIZE = 3;
58	const BLOCK_BASE_PREMIUM = 60;
59	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
60	
61	const countByType = (items: Item[]): Map<string, number> => {
62	  const counts = new Map<string, number>();
63	  for (const item of items) {
64	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
65	  }
66	  return counts;
67	};
68	
69	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
70	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
71	// items never form a block.
72	const basePremiumForAlikeItems = (type: string, count: number): number =>
73	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
74	    ? BLOCK_BASE_PREMIUM
75	    : count * BASE_PREMIUM_BY_TYPE[type];
76	
77	const policyBasePremiumOf = (items: Item[]): number =>
78	  [...countByType(items)].reduce(
79	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
80	    0,
81	  );
82	
83	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
84	  const results = scenario.steps.map((step) => {
85	    const policyBasePremium = policyBasePremiumOf(step.items);
86	    const premium =
87	      policyBasePremium +
88	      itemSurchargesOf(step.items) +
89	      firstInsuranceSurchargeOn(policyBasePremium) +
90	      PROCESSING_FEE;
91	    return { premium };
92	  });
93	
94	  return { results };
95	};
